<template><div><div class="flex items-end justify-between"><div><h1 class="text-3xl font-bold">Ressources</h1><p class="mt-2 text-[var(--muted)]">Fichiers protégés et métadonnées publiques.</p></div></div><div class="mt-8 grid gap-7 xl:grid-cols-[.8fr_1.2fr]"><form class="card space-y-4" @submit.prevent="create"><h2 class="text-xl font-bold">Nouvelle ressource</h2><input v-model="form.title" class="field" placeholder="Titre" required/><textarea v-model="form.description" class="field min-h-24 py-3" placeholder="Description" required/><div class="grid grid-cols-2 gap-3"><select v-model="form.type" class="field"><option>pdf</option><option>video</option><option>image</option><option>template</option><option>link</option></select><input v-model="form.sector" class="field" placeholder="Secteur" required/></div><input v-model="form.fileKey" class="field" placeholder="Fichier (ou téléverser ci-dessous)" required/><input type="file" accept="application/pdf,application/zip,video/mp4" class="block w-full text-sm" @change="upload"/><div class="flex items-center gap-4 border-t pt-4"><img v-if="coverUrl" :src="coverUrl" alt="" class="h-14 w-20 rounded-lg object-cover"/><div class="flex-1"><input type="file" accept="image/png,image/jpeg,image/webp" class="block w-full text-sm" @change="uploadCover"/><p class="mt-1 text-xs text-[var(--muted)]">Image de couverture (optionnel)</p></div></div><label class="flex gap-2 text-sm"><input v-model="form.published" type="checkbox"/>Publier immédiatement</label><p v-if="notice" class="text-sm text-violet-700">{{ notice }}</p><button class="btn-primary w-full">Créer</button></form><div class="space-y-3"><article v-for="item in data?.items" :key="item._id" class="card flex flex-col gap-4 sm:flex-row sm:items-center"><div class="flex-1"><p class="font-bold">{{ item.title }}</p><p class="mt-1 text-xs text-[var(--muted)]">{{ item.sector }} · {{ item.type }} · {{ item.leadCount||0 }} leads</p></div><button class="rounded-lg border px-3 py-2 text-xs font-bold" @click="toggle(item)">{{ item.published?'Dépublier':'Publier' }}</button><button class="rounded-lg bg-red-500/10 px-3 py-2 text-xs font-bold text-red-700" @click="remove(item._id)">Supprimer</button></article></div></div></div></template>
<script setup lang="ts">definePageMeta({middleware:'admin',layout:'admin',i18n:{locales:['fr']}});useSeoMeta({title:'Ressources',robots:'noindex,nofollow'});const {data,refresh}=await useFetch<any>('/api/admin/resources');const notice=ref(''),form=reactive({title:'',description:'',type:'pdf',sector:'Acquisition',fileKey:'',coverImageKey:'',published:false});const cld=useCloudinaryUrl();const coverUrl=computed(()=>cld(form.coverImageKey,'w_200,h_140,c_fill'));async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;const body=new FormData();body.append('file',file);notice.value='Téléversement…';try{const r=await $fetch<any>('/api/admin/upload?folder=resources',{method:'POST',body});form.fileKey=r.key;notice.value='Fichier téléversé.'}catch(err:any){notice.value=err?.data?.statusMessage||'Échec du téléversement'}}async function uploadCover(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;const body=new FormData();body.append('file',file);try{const r=await $fetch<any>('/api/admin/upload?folder=resources',{method:'POST',body});form.coverImageKey=r.key}catch(err:any){notice.value=err?.data?.statusMessage||'Échec du téléversement'}}async function create(){await $fetch('/api/admin/resources',{method:'POST',body:{...form,coverImageKey:form.coverImageKey||undefined}});Object.assign(form,{title:'',description:'',type:'pdf',sector:'Acquisition',fileKey:'',coverImageKey:'',published:false});await refresh()}async function toggle(item:any){await $fetch(`/api/admin/resources/${item._id}`,{method:'PATCH',body:{published:!item.published}});await refresh()}async function remove(id:string){if(confirm('Supprimer cette ressource ?')){await $fetch(`/api/admin/resources/${id}`,{method:'DELETE'});await refresh()}}</script>
